mapper.select:
SELECT generation,
    event_seq AS sequence,
    event_type AS type,
    payload_json,
    occurred_at
FROM sq_conversation_event
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND generation = #{generation}
  AND event_seq > #{after}
ORDER BY event_seq
LIMIT 100

SELECT MIN(event_seq)
FROM sq_conversation_event
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND generation = #{generation}

SELECT origin_message_id
FROM sq_goal_task
WHERE user_id = #{userId}
  AND task_id = #{taskId}

mapper.update:
UPDATE sq_message
SET content    = #{text},
    revision   = #{revision},
    completed  = TRUE
WHERE user_id = #{userId}
  AND message_id = #{messageId}
  AND revision <= #{revision}

mapper.select:
SELECT id
FROM sq_conversation
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}

mapper.update:
UPDATE sq_conversation
SET title         = #{title},
    title_source  = 'MANUAL',
    title_version = title_version + 1,
    version       = version + 1
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND title_version = #{version}
  AND status = 'ACTIVE'
